const CACHE='nur-mobile-v6-light';
const SHELL=['./','./index.html','./style.css','./theme.css','./guide.js','./compact.js','./i18n.js','./enhancements.js','./mobile.js','./app.js','./manifest.webmanifest','./icons/basira-logo.png','./icons/icon-192.png','./icons/icon-512.png','./icons/icon-maskable-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('nur-mobile-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match(new URL('./index.html',self.registration.scope).href)));return}if(!SHELL.some(p=>new URL(p,self.registration.scope).pathname===u.pathname))return;event.respondWith(fetch(event.request).then(res=>{if(res.ok){const clone=res.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(event.request,clone)))}return res}).catch(()=>caches.match(event.request,{ignoreSearch:true})))});
